// Nur echte Zahlen-IDs, höchstens 30 auf einmal (Kostenbremse)
let b = $('Start von der Seite').first().json.body || {};
if (typeof b === 'string') {
  try {
    b = JSON.parse(b);
  } catch (e) {
    b = {};
  }
}
const ids = [...new Set((Array.isArray(b.ids) ? b.ids : []).map(Number).filter((x) => Number.isInteger(x) && x > 0))].slice(0, 40);
// Pro Stelle: Art der Mappe (voll / kurz / keins) und ggf. Modell – von der Seite (Ampel + gewünschte Unterlagen)
const wunsch = {};
for (const s of Array.isArray(b.stellen) ? b.stellen : []) {
  const art = ['voll', 'kurz', 'keins'].includes(s.art) ? s.art : 'voll';
  const modell = /^claude-[a-z0-9-]{3,40}$/.test(String(s.modell || '')) ? s.modell : '';
  wunsch[Number(s.id)] = { art, modell, bereich: String(s.bereich || '').slice(0, 80) };
}
const zeilen = {};
for (const i of $('Alle Stellen laden').all()) if (i.json.id) zeilen[i.json.id] = { ...i.json };
for (const i of $('Meine Notizen laden').all()) {
  const z = zeilen[i.json.job_id];
  if (z) z.meine_notiz = i.json.notiz || '';
}
for (const i of $('Tiefen-Checks laden').all()) {
  const z = zeilen[i.json.job_id];
  if (z) z.tc_ergebnis = i.json.ergebnis || '';
}
const aus = ids.filter((id) => zeilen[id]).map((id) => ({ json: { ...zeilen[id], _art: (wunsch[id] || {}).art || 'voll', _modell: (wunsch[id] || {}).modell || '', _bereich: (wunsch[id] || {}).bereich || '' } }));
return aus.length ? aus : [{ json: { _leer: true } }];

const row = $('Schleife: eine Stelle nach der anderen').first().json;
const cache = $('Seitentext aus Cache').first().json;
const p = $('Profil laden').first().json || {};
// Lebenslauf des Bereichs der Stelle (Zeilen aus den Einstellungen); was dort fehlt, ersetzt der Standard
const lebenslaufFuer = (bereich, en) => {
  const w = String(bereich || '').trim().toLowerCase();
  const z = w ? (p.lebenslaeufe || []).find((x) => String(x.bereich || '').trim().toLowerCase() === w) : null;
  const reihe = en ? [z && z.text_en, p.lebenslauf_en_text, z && z.text_de, p.lebenslauf_text] : [z && z.text_de, p.lebenslauf_text];
  return reihe.find(Boolean) || '';
};
// Stil-Text aus den Einstellungen: ist er eine komplette Chat-Vorlage, gehört alles ab dem Trenner „---“ (Auftrag + leere
// Datenabschnitte) nicht hinein, ebenso Abschnitte, die nur einen Platzhalter enthalten – die echten Daten folgen unten im Prompt.
const stilBereinigen = (s) => String(s || '')
  .split(/\n-{3,}\s*\n/)[0]
  .replace(/^#{1,6} [^\n]*\n(?:[ \t]*\n)*[ \t]*\{\{\w+\}\}[ \t]*(?:\n|$)/gm, '')
  .replace(/^[ \t]*\{\{\w+\}\}[ \t]*$/gm, '')
  .replace(/\n{3,}/g, '\n\n')
  .trim();
const vorlage = String($('Anschreiben-Prompt laden').first().json.text || '').split('\n').filter((z) => !/^#(?!#)/.test(z)) /* '# …' = Kommentar, '## …' = Überschrift bleibt */.join('\n');
const [system, anfrage] = vorlage.split('=== ANFRAGE ===').map((t) => t.trim());
// Sprache der Anzeige grob erkennen (häufige englische vs. deutsche Wörter)
const anzeige = String((cache && cache.text) || '');
const zaehl = (re) => (anzeige.match(re) || []).length;
const englisch = zaehl(/\b(the|and|you|with|our|we|for)\b/g) > zaehl(/\b(und|die|der|wir|mit|für|Sie|du)\b/g);
const fuellen = (t, werte) => t.replace(/\{\{(\w+)\}\}/g, (m, key) => (key in werte ? werte[key] : m));
const fakten = [
  `Jobtitel: ${row.jobtitel || '-'}`, `Firma: ${row.firma || '-'}`, `Ort: ${row.ort || '-'}`, `Remote: ${row.remote || '-'}`,
  `Gehalt: ${row.gehalt || '-'}`, `Vertragsform: ${row.vertragsform || '-'}`, `Bewerbungsweg: ${row.bewerbungsweg || '-'}`,
].join('\n');
// Tiefen-Check kompakt: Empfehlung, Argumente, Anforderungen
let tc = '(kein Tiefen-Check vorhanden)';
try {
  const d = JSON.parse(row.tc_ergebnis || '');
  tc = [
    `Empfehlung: ${d.empfehlung || d.ampel || '-'} – ${d.kurzfazit || d.fazit || ''}`,
    d.aufgaben_vergleich ? `Aufgaben vs. Person: ${d.aufgaben_vergleich.urteil || ''}` : '',
    'Stärkste Argumente:\n' + (d.argumente || []).map((a) => '- ' + a).join('\n'),
    'Anforderungen:\n' + (d.anforderungen || []).map((a) => `- ${a.anforderung}: ${a.status} (${a.beleg || ''})`).join('\n'),
  ].filter(Boolean).join('\n\n');
} catch (e) {
  /* kein gültiger Check */
}
// Art der Mappe: voll = normales Anschreiben, kurz = Kurzfassung, keins = Firma will keins → nur Kurznachricht
const art = row._art || 'voll';
const AUFTRAG = {
  voll: 'Schreibe das Anschreiben wie oben beschrieben. Zusätzlich das Feld "kurznachricht".',
  kurz: 'Die Anzeige sagt nicht klar, ob ein Anschreiben gewünscht ist. Schreibe deshalb eine KOMPAKTE Fassung mit demselben Aufbau: Einstieg mit dem Problem der Firma, EIN Belegabsatz mit dem passendsten Beleg und dem Nutzen für die Firma, kurzer Schluss. 120 bis 160 Wörter, keine Ein-Satz-Absätze. Zusätzlich das Feld "kurznachricht".',
  keins: 'Die Firma will KEIN Anschreiben. Lass "absaetze" leer ([]) und schreibe NUR das Feld "kurznachricht". Betreff, Anrede und Gruß trotzdem ausfüllen.',
}[art];
const SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['sprache', 'betreff', 'anrede', 'absaetze', 'gruss', 'firmensitz', 'strasse', 'plz_ort', 'kurznachricht'],
  properties: {
    kurznachricht: {
      type: 'string',
      description: '3–4 Sätze für das Nachrichtenfeld im Bewerbungsformular oder als E-Mail-Text, in der Sprache der Anzeige: wer ich bin, warum genau diese Stelle (ein konkreter Punkt), Hinweis auf den Lebenslauf im Anhang. Gleiche Regeln wie beim Anschreiben (förmlich, keine Floskeln, keine Doppelpunkte). Mit kurzer Anrede, ohne Grußformel.',
    },
    sprache: { type: 'string', enum: ['de', 'en'] },
    betreff: { type: 'string', description: 'Kurz: "Bewerbung als <Kern-Stellentitel>" – OHNE (m/w/d) und ohne Zusätze nach Bindestrich, z. B. "Bewerbung als AI Product Builder"' },
    anrede: { type: 'string', description: 'Förmlich: "Sehr geehrte Frau Muster," / "Sehr geehrtes Metanoia-Team," / englisch "Dear Ms Muster," bzw. "Dear Hiring Team," – nie "Hallo"' },
    strasse: { type: 'string', description: 'Straße und Hausnummer der Firma, NUR wenn sie in der Anzeige steht – sonst ""' },
    plz_ort: { type: 'string', description: 'PLZ und Ort der Firma, NUR wenn die PLZ in der Anzeige steht – sonst ""' },
    absaetze: { type: 'array', items: { type: 'string' }, description: 'Nur der Brieftext, 3–5 Absätze, ohne Anrede und Gruß' },
    gruss: { type: 'string', description: 'z. B. "Viele Grüße" / "Best regards" – ohne Namen' },
    firmensitz: { type: 'string', description: 'Stadt der Firma kurz, z. B. "Wien" – oder "remote"' },
  },
};
return [
  {
    json: {
      system,
      anfrage: fuellen(anfrage, {
        HEUTE: $now.toFormat('yyyy-MM-dd'),
        STIL: stilBereinigen(p.anschreiben_prompt) || '(keine Vorgaben – schreibe knapp, konkret, ohne Floskeln)',
        BEISPIEL: p.beispiel_text || '(kein Beispiel hinterlegt)',
        // Englische Anzeige + englischer CV vorhanden → den nehmen (passende Formulierungen)
        LEBENSLAUF: lebenslaufFuer(row._bereich, englisch) || '(kein Lebenslauf hochgeladen)',
        FAKTEN: fakten,
        TIEFENCHECK: tc,
        NOTIZ: String(row.meine_notiz || '').trim() || '(keine)',
        SEITENTEXT: '{{SEITENTEXT}}',
      }) + `\n\n## Auftrag für diese Stelle\n${AUFTRAG}`, // hinten anhängen – der zwischengespeicherte Anfang bleibt gleich
      seitentext: cache && cache.ok ? String(cache.text) : '(kein Seitentext im Cache – nur Fakten verwenden)',
      schema: SCHEMA,
      funktion: 'anschreiben', // Modell laut ⚙️ Einstellungen …
      claude_modell_zwang: row._modell || '', // … außer die Seite gibt eins vor (z. B. gelb → Sonnet, ohne Anschreiben → Haiku)
      claude_effort_override: 'medium',
      kontext: { id: row.id, firma: row.firma || row.domain || '', stelle: row.jobtitel || row.linktext || '', art, bereich: row._bereich || '' },
    },
  },
];

const r = $json;
const k = r.kontext || {};
if (!r.ok) return [{ json: { job_id: k.id, fehler: r.fehler || 'keine Antwort' } }];
const d = r.daten || {};
return [{ json: { job_id: k.id, firma: k.firma, stelle: k.stelle, art: k.art || 'voll', bereich: k.bereich || '', ...d, modell: `${r.anbieter}:${r.modell}` } }];
